{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "버스정류장 옆 편의점 의자에서 담배를 피운 경우, 정류장 바로 앞이 아니어도 금연구역에 해당하여 과태료가 부과되는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 금연환경 조성 및 간접흡연 피해방지조례 제5조제1항제7호는 시 관할 구역의 버스정류소 및 택시 승차대를 금연구역으로 지정할 수 있는 장소로 정하고 있습니다. 같은 조 제4항은 누구든지 제1항에 따라 지정된 금연구역에서 흡연을 해서는 아니된다고 규정합니다. 따라서 버스정류소 자체가 금연구역으로 지정된 경우, 정류장 바로 앞이 아니더라도 그 정류소에 해당하면 금연구역에 해당할 수 있습니다. 다만, 편의점 의자에서 담배를 피운 장소가 실제로 버스정류소 구역에 포함되는지, 그리고 그 장소가 제5조제1항에 따라 금연구역으로 지정되었는지는 이 원문만으로 확인되지 않습니다. 제10조제1항은 제5조제4항을 위반하여 금연구역에서 흡연한 사람에게 10만원의 과태료를 부과·징수한다고 정합니다.",
          "b_ids": "금연:제5조제1항제7호, 금연:제5조제4항, 금연:제10조제1항"
        }
      ],
      "e_status": "SIDE_MISSING"
    }
  ]
}
